import{z as i,x as A,o as l,c as p,q as r,j as t,D as e,d as s,s as o,S as n}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"RTFM：探索时实时出帧而非导出场景","description":"","frontmatter":{"title":"RTFM：探索时实时出帧而非导出场景","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/worldlabs-rtfm.md","filePath":"llm/worldlabs-rtfm.md","lastUpdated":1791063341000}'),B={name:"llm/worldlabs-rtfm.md"};function m(d,a,F,T,h,b){const E=A("Mermaid");return l(),p("div",null,[a[2]||(a[2]=r('<h1 id="rtfm-探索时实时出帧而非导出场景" tabindex="-1">RTFM：探索时实时出帧而非导出场景 <a class="header-anchor" href="#rtfm-探索时实时出帧而非导出场景" aria-label="Permalink to &quot;RTFM：探索时实时出帧而非导出场景&quot;">​</a></h1><div class="epigraph"><p>不必先把世界写成网格或高斯再光栅化；把当前视图像查询，让网络在交互帧率下直接画出下一帧，世界以带位姿的帧为记忆。</p><footer>—— 归纳自 World Labs, RTFM: A Real-Time Frame Model</footer></div><p>Marble 路线把生成结果落成可导出的三维资产，再用 <a href="/llm/marble-spark">Spark</a> 在浏览器里画。RTFM（Real-Time Frame Model）走另一条：不先导出完整 mesh 或 splat 场景，用户在探索时由模型按当前位姿实时出帧。World Labs 把它写成研究预览：单卡 H100 上交互帧率，世界在转身离开后仍应可回去。这与 <a href="/llm/persistent-3d-vs-streaming-frames">持久三维世界 vs 边走边生成帧</a> 是同一分叉的生成侧实现。本篇讲任务与系统选择；形变等失败模式见 <a href="/llm/rtfm-morphing">实时世界模型的形变与不一致性</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若把现代视频架构直接当成交互世界，算力会先爆。官方估算：交互 4K、60 fps 意味着每秒超过 \\(10^5\\) 量级 token；若再让注意力窗口覆盖一小时探索，上下文可到 \\(10^8\\) token。这在今天的集群上既不经济，也无法塞进一张推理卡。传统图形学的回答是：先有显式三维（三角网、3DGS），再光栅——探索成本与场景复杂度相关，与「生成过多少帧」无关。生成式世界若坚持显式资产，就必须走 Marble 的导出；若坚持从视频数据端到端学习反射、高光、阴影，显式资产又成了手写归纳偏置，不易随数据规模变好。</p><p><span class="marginnote">\\(10^5\\) token/秒是什么量级：LLM 聊天时每秒吐几十个词，视频模型把像素切成小块后，4K 60 fps 一秒就要「写」十几万个小块，整整高出三四个数量级；一小时探索再堆到 \\(10^8\\) token 的上下文，更是任何单卡注意力都装不下的。这就是为什么「直接拿视频模型当世界」走不通，需要换记忆方案。</span></p><p>RTFM 要同时满足三件事：今天就能在单 H100 上交互；架构仍能随数据与算力放大；探索多久都不该把走过的地方忘掉。这迫使它把「渲染」定义成神经网络的前向，而不是导出后再画。</p><h3 id="出帧与导出是两种持久性" tabindex="-1">出帧与导出是两种持久性 <a class="header-anchor" href="#出帧与导出是两种持久性" aria-label="Permalink to &quot;出帧与导出是两种持久性&quot;">​</a></h3><p>导出场景的持久性在资产文件里：高斯或网格在磁盘上，关掉浏览器再打开还在。实时出帧的持久性必须在模型状态里：KV、检索到的旧帧、或某种外部记忆。没有显式几何时，「还在」的含义变成：再查询靠近旧位姿的相机，能否得到与当时相容的像素。这比文件持久更弱，也更便宜——不必为尚未走到的角落实例化上千万 splat。</p><p><span class="marginnote">RTFM 可以与 Marble 串联：用 Marble 从单图生成世界，再让 RTFM 当学习到的渲染器去画反射与高光。此时 Marble 仍可能持有 splat，但 RTFM 自己并不依赖把这些 splat 读进着色器。两条表示可以并存，不要写成 RTFM 替换了 3DGS。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>RTFM 吃一张或多张场景的二维图，直接生成新视点的二维图，中间不构建显式三维。实现上是自回归扩散 Transformer：在帧序列上训练，条件于已有帧预测下一帧。输入帧被编成网络激活（KV cache），生成时用注意力读这份隐式世界。反射、光泽、阴影、镜头光晕等，靠在大规模视频里看见过，而不是写 BRDF。</p><p>位姿是一等条件。每一帧带三维位置与朝向；生成新帧时用待生成帧的位姿去查询模型。世界记忆因此是「带位姿的帧」，不是无序的视频 clip。这给出弱先验——世界是三维欧氏空间——但不强迫预测物体表面的三维坐标。当输入视很多，任务更像新视合成（插值）；视很少，则必须外推、想象未见区域。重建与生成被同一网络按条件松紧切换。</p>',13)),(l(),t(n,null,{default:e(()=>[o(E,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20I%5B%22%E8%BE%93%E5%85%A5%E8%A7%86%E5%9B%BE%E5%83%8F%22%5D%20--%3E%20K%5B%22%E7%BC%96%E6%88%90%20KV%20%2F%20%E9%9A%90%E5%BC%8F%E4%B8%96%E7%95%8C%22%5D%0A%20%20P%5B%22%E6%9F%A5%E8%AF%A2%E4%BD%8D%E5%A7%BF%22%5D%20--%3E%20G%5B%22%E8%87%AA%E5%9B%9E%E5%BD%92%E6%89%A9%E6%95%A3%E5%87%BA%E5%B8%A7%22%5D%0A%20%20K%20--%3E%20G%0A%20%20M%5B%22%E7%A9%BA%E9%97%B4%E8%AE%B0%E5%BF%86%E4%B8%AD%E7%9A%84%E8%BF%91%E9%82%BB%E5%B8%A7%22%5D%20--%3E%20J%5B%22context%20juggling%22%5D%0A%20%20J%20--%3E%20G%0A%20%20G%20--%3E%20F%5B%22%E5%BD%93%E5%89%8D%E5%B8%A7%22%5D%0A%20%20F%20--%3E%20M%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<h3 id="context-juggling" tabindex="-1">Context juggling <a class="header-anchor" href="#context-juggling" aria-label="Permalink to &quot;Context juggling&quot;">​</a></h3><p>朴素自回归会把所有历史帧留在上下文里，每多走一步，下一帧更贵，记忆被算力上限截断。RTFM 按空间取近邻帧组成当前上下文，官方称为 context juggling：在不同区域生成时用不同的条件帧。于是大世界的持久不必对「曾经见过的每一帧」做全注意力，只要在查询位姿附近找回相关帧。这是用空间索引换序列长度，和语言模型的无限上下文不是同一算法，但动机同构：不要让历史线性堆死解码。</p><p><span class="marginnote">「单 H100 交互」是系统设计目标，不是一条与分辨率、视场、步数无关的定理。扩散步数、是否蒸馏、输出分辨率都会改帧率。博客没有给出可引用的 fps 表；不要编造。</span></p><h3 id="与-marble-导出路径的分工" tabindex="-1">与 Marble 导出路径的分工 <a class="header-anchor" href="#与-marble-导出路径的分工" aria-label="Permalink to &quot;与 Marble 导出路径的分工&quot;">​</a></h3><p>Marble 把世界写成可下载的 splat 或网格，探索成本在光栅；RTFM 把世界写成可查询的帧模型，探索成本在网络前向。前者适合要进引擎、要碰撞、要分享文件的工作流；后者适合要立刻走进、且显式资产还来不及或不必实例化的预览。官方可以把二者串起来：Marble 出世界，RTFM 当学习到的渲染器补反射。不要把「实时出帧」理解成已经淘汰了 Kerbl 的 3DGS——没有资产时物理与导出都会缺一块。</p><p><span class="marginnote">出帧路线的记忆在 KV 与检索集里，进程一杀就没有文件可备份。若用户需要可版本管理的世界，仍应导出 splat。RTFM 的 persistence 是交互过程中的空间记忆，不是 git 里的资产。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>把世界模型当成学习到的渲染器，等于把图形学里手写的可见性、材质、光照，全部折进权重。可微的只有「给定条件帧与位姿，像素应如何」。位姿条件让同一套权重能被问「从这边看是什么」，否则网络只是视频续写，相机一自由就与训练时的剪辑统计打架。自回归提供时间上的因果接口：已经生成的帧成为后续条件，探索过程本身在写记忆。扩散则负责高维连续像素；帧不是离散词表上的 token，不能只用交叉熵。</p><p>与 Kerbl 3DGS 对照：3DGS 把世界写成可排序的高斯，浏览器里用 <a href="/llm/marble-spark">Spark</a> 画，探索不调用生成网络。RTFM 把世界写在激活里，每帧都要跑网络，换来的是数据驱动的外观，以及不必为整个场景分配 splat 显存。二者都不是「更正确的世界」，而是持久性放在文件还是放在推理状态。</p>',9)),(l(),t(n,null,{default:e(()=>[o(E,{id:"mermaid-65",class:"mermaid",graph:"flowchart%20LR%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%E4%B8%80%E4%B8%AA%E6%96%B0%E8%A7%86%E8%A7%92%22%5D%20--%3E%20A%5B%22RTFM%EF%BC%9A%E8%B7%91%E4%B8%80%E6%AC%A1%E7%BD%91%E7%BB%9C%E5%89%8D%E5%90%91%22%5D%0A%20%20Q%20--%3E%20B%5B%223DGS%EF%BC%9A%E6%8E%92%E5%BA%8F%E5%B9%B6%E5%85%89%E6%A0%85%E5%8C%96%E9%AB%98%E6%96%AF%22%5D%0A%20%20A%20--%3E%20A1%5B%22%E6%88%90%E6%9C%AC%E9%9A%8F%E6%A8%A1%E5%9E%8B%E5%89%8D%E5%90%91%EF%BC%8C%E5%A4%96%E8%A7%82%E7%94%B1%E8%A7%86%E9%A2%91%E6%95%B0%E6%8D%AE%E5%AD%A6%E5%BE%97%22%5D%0A%20%20B%20--%3E%20B1%5B%22%E6%88%90%E6%9C%AC%E9%9A%8F%E5%9C%BA%E6%99%AF%E9%AB%98%E6%96%AF%E6%95%B0%EF%BC%8C%E5%A4%96%E8%A7%82%E9%9C%80%E5%85%88%E7%83%98%E7%84%99%E6%88%90%E8%B5%84%E4%BA%A7%22%5D%0A%20%20A1%20--%3E%20A2%5B%22%E6%8C%81%E4%B9%85%E6%80%A7%E5%9C%A8%20KV%20%E4%B8%8E%E7%A9%BA%E9%97%B4%E6%A3%80%E7%B4%A2%E8%AE%B0%E5%BF%86%22%5D%0A%20%20B1%20--%3E%20B2%5B%22%E6%8C%81%E4%B9%85%E6%80%A7%E5%9C%A8%E7%A3%81%E7%9B%98%E4%B8%8A%E7%9A%84%20splat%20%2F%20%E7%BD%91%E6%A0%BC%E6%96%87%E4%BB%B6%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<p><span class="marginnote">直觉类比：3DGS 像「把景点先做成沙盘模型」，去看的时候不用重新造，但做沙盘本身要工时与仓库；RTFM 像「一位去过那里的画师凭记忆现场作画」，省掉了搭沙盘的成本，反射高光也画得更活，但每次看都要画师（网络）出场，而且记忆可能走样。选哪条路，取决于你要可带走的资产，还是要立刻走进去。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>没有显式几何，物理、碰撞、机器人仿真不能直接读表面。需要资产时仍应走 Marble 导出。实时出帧的失败模式是形变与多视不一致：记忆检索漏了、位姿量化粗了、或外推过远，像素会在本该刚体的地方流动。官方强调 persistence，并不等于几何定理；评测应看「走远再回来」而不是只看单段漂亮运镜。</p><p><span class="marginnote">初学者容易把「世界还在」理解成「几何保真地还在」。实际上出帧路线的持久性只承诺：回到旧位姿附近，能生成出与当时相容的像素——柜子背面长什么样、桌子有没有被记对，可能从未被真正确定。所以测这类模型要用「走远再回头」的轨迹，看回来时物体是否还是原样，而不是只看单段运镜顺不顺。</span></p><p>架构细节（层数、潜空间、是否整流流）在 RTFM 博客里没有写成可核对的配置。Atlas 后来把自回归扩散 Transformer 说得更完整，并明确整流流与潜扩散；不要把 Atlas 的模块表倒填进 RTFM，也不要给 RTFM 造一份 arXiv。出处就是 World Labs, <em>RTFM: A Real-Time Frame Model</em>（2025 博客）。Ho 的 DDPM 与后续视频扩散提供「帧是连续数据、用去噪生成」的背景，不是 RTFM 的论文声明。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RTFM = Real-Time Frame Model：探索时按位姿实时生成二维帧，不先导出完整 mesh/splat 再光栅。</li><li>它是自回归扩散 Transformer，用 KV 中的帧当作学习到的渲染器，从视频数据里学反射等高阶效果。</li><li>每帧带三维位姿；context juggling 按空间取近邻帧，使持久不必让上下文随探索线性膨胀。</li><li>视多偏重建、视少偏生成，同一网络按条件松紧切换。</li><li>单 H100 交互是系统目标；分辨率与采样步未公开成表，勿编造。</li><li>对照 Kerbl 3DGS：资产持久 vs 推理期出帧。形变与不一致性是这条路线的代价，见下一篇。</li><li>出处：World Labs RTFM 博客，无 World Labs arXiv 号可填。</li></ul>',7))])}const f=i(B,[["render",m]]);export{c as __pageData,f as default};
